            return false;
        }
        if (processType != AppExecFwk::ProcessType::NORMAL) {
            NETMGR_EXT_LOG_I("IsCurrentVpnPid skip non-main process, pid: %{public}d, processType: %{public}d",
                pid, static_cast<int32_t>(processType));
            return false;
        }
        isMainProc = true;
        return true;
    }
    // LCOV_EXCL_STOP
    return false;
}

