static ErrCode JumpToSettingsPageByNavKey(const std::shared_ptr<BaseContext> &asyncContext, const std::string &navKey)
{
    SETTING_LOG_INFO("JumpToSettingsPageByNavKey start");
    if (asyncContext == nullptr) {
        SETTING_LOG_ERROR("asyncContext is nullptr");
        return ERR_INVALID_VALUE;
    }

    OHOS::AAFwk::Want want;
    if (DEVICE_TYPE == OHOS::Settings::DeviceType::WEARABLE) {
        want.SetElementName(SETTINGS_PACKAGE_NAME, navKey);
    } else {
        want.SetElementName(SETTINGS_PACKAGE_NAME, SETTINGS_MAIN_ABILITY_NAME);
        want.SetUri(navKey);
    }

    if (asyncContext->abilityContext != nullptr) {
        return asyncContext->abilityContext->StartAbility(want, DEFAULT_INVAL_VALUE);
    } else if (asyncContext->uiExtensionContext != nullptr) {
        return asyncContext->uiExtensionContext->StartAbility(want);
    } else {
        SETTING_LOG_ERROR("abilityContext and uiExtensionContext is nullptr");
        return ERR_INVALID_VALUE;
    }
}

static ErrCode JumpToSettingsPageByNavKeyWithWant(const std::shared_ptr<BaseContext> &asyncContext,
    const std::string &navKey, OHOS::AAFwk::Want &want)
{
    SETTING_LOG_INFO("JumpToSettingsPageByNavKey with want start");
    if (asyncContext == nullptr) {
        SETTING_LOG_ERROR("asyncContext is nullptr");
        return ERR_INVALID_VALUE;
    }

    want.SetElementName(SETTINGS_PACKAGE_NAME, SETTINGS_MAIN_ABILITY_NAME);
    want.SetUri(navKey);

    if (asyncContext->abilityContext != nullptr) {
        return asyncContext->abilityContext->StartAbility(want, DEFAULT_INVAL_VALUE);
    } else if (asyncContext->uiExtensionContext != nullptr) {
        return asyncContext->uiExtensionContext->StartAbility(want);
    } else {
        SETTING_LOG_ERROR("abilityContext and uiExtensionContext is nullptr");
        return ERR_INVALID_VALUE;
    }
}

static bool OpenSettingsPage(napi_env env, napi_callback_info info, const std::string &navKey)
{
    if (!IsPageSupportJump(DEVICE_TYPE, navKey)) {
        SETTING_LOG_ERROR("The device type is not supported.");
        return false;
    }

    size_t argc = ARGS_ONE;
    napi_value argv[ARGS_ONE] = {nullptr};
    napi_status status = napi_get_cb_info(env, info, &argc, argv, nullptr, nullptr);
    if (status != napi_ok) {
        SETTING_LOG_ERROR("napi_get_cb_info failed.");
        ThrowExistingError(env, SETTINGS_PARAM_INVALID_CODE, "The parameters is invalid.");
        return false;
    }
    if (argc < ARGS_ONE) {
        SETTING_LOG_ERROR("The number of parameters is less than 1.");
        ThrowExistingError(env, SETTINGS_PARAM_INVALID_CODE, "The number of parameters is less than 1.");
        return false;
    }
    auto loadProductContext = std::make_shared<BaseContext>();
    if (!ParseAbilityContext(env, argv[PARAM0], loadProductContext->abilityContext,
        loadProductContext->uiExtensionContext)) {
        SETTING_LOG_ERROR("context parse error.");
        ThrowExistingError(env, SETTINGS_PARAM_INVALID_CODE, "The context parameter is invalid.");
        return false;
    }

    auto ret = JumpToSettingsPageByNavKey(loadProductContext, navKey);
    if (ret != ERR_OK) {
        SETTING_LOG_ERROR("Failed to start the page, navKey: %{public}s, ret: %{public}d", navKey.c_str(), ret);
        ThrowExistingError(env, SETTINGS_START_PAGE_FAILED_CODE, "Failed to start the page.");
        return false;
    }
    SETTING_LOG_INFO("Start the page successfully, navKey: %{public}s.", navKey.c_str());
    return true;
}

static bool OpenSettingsPageWithWant(napi_env env, const napi_value &context, const std::string &navKey,
    OHOS::AAFwk::Want &want)
{
    if (!IsPageSupportJump(DEVICE_TYPE, navKey)) {
        SETTING_LOG_ERROR("The device type is not supported.");
        return false;
    }

    auto loadProductContext = std::make_shared<BaseContext>();
    if (!ParseAbilityContext(env, context, loadProductContext->abilityContext,
        loadProductContext->uiExtensionContext)) {
        SETTING_LOG_ERROR("context parse error.");
        ThrowExistingError(env, SETTINGS_PARAM_INVALID_CODE, "The context parameter is invalid.");
        return false;
    }

    auto ret = JumpToSettingsPageByNavKeyWithWant(loadProductContext, navKey, want);
    if (ret != ERR_OK) {
        SETTING_LOG_ERROR("Failed to start the page, navKey: %{public}s, ret: %{public}d", navKey.c_str(), ret);
        ThrowExistingError(env, SETTINGS_START_PAGE_FAILED_CODE, "Failed to start the page.");
        return false;
    }
    SETTING_LOG_INFO("Start the page successfully, navKey: %{public}s.", navKey.c_str());
    return true;
}

static napi_value OpenSettingsPageCommon(napi_env env, napi_callback_info info, const std::string &pageUrl,
    std::function<bool()> checkFunc = nullptr, const std::string &errorMsg = "")
{
    SETTING_LOG_INFO("OpenSettingsPageCommon start, pageUrl: %{public}s.", pageUrl.c_str());
    napi_value result = nullptr;
    napi_get_undefined(env, &result);

    if (checkFunc != nullptr && !checkFunc()) {
        if (!errorMsg.empty()) {
            SETTING_LOG_ERROR("%{public}s.", errorMsg.c_str());
        }
        ReportSysEvent(pageUrl, false);
        return result;
    }

    bool ret = OpenSettingsPage(env, info, pageUrl);
    ReportSysEvent(pageUrl, ret);
    return result;
}

bool StartUiExtensionAbility(OHOS::AAFwk::Want &request, std::shared_ptr<BaseContext> &asyncContext)
{
    SETTING_LOG_INFO("begin StartUiExtensionAbility");
    if (asyncContext == nullptr) {
        SETTING_LOG_ERROR("asyncContext is nullptr");
        return false;
    }

    if (asyncContext->abilityContext == nullptr && asyncContext->uiExtensionContext == nullptr) {
        SETTING_LOG_ERROR("abilityContext is nullptr");
        return false;
    }

    auto uiContent = GetUIContent(asyncContext);
    if (uiContent == nullptr) {
        SETTING_LOG_ERROR("UIContent is nullptr");
        return false;
    }
    std::string info = uiContent->GetContentInfo();
    auto callback = std::make_shared<ModalUICallback>(asyncContext);
    OHOS::Ace::ModalUIExtensionCallbacks extensionCallbacks = {
        std::bind(&ModalUICallback::OnRelease, callback, std::placeholders::_1),
        std::bind(&ModalUICallback::OnResultForModal, callback, std::placeholders::_1, std::placeholders::_2),
        std::bind(&ModalUICallback::OnReceive, callback, std::placeholders::_1),
        std::bind(&ModalUICallback::OnError, callback, std::placeholders::_1, std::placeholders::_2,
            std::placeholders::_3),
    };

    OHOS::Ace::ModalUIExtensionConfig config;
    config.isProhibitBack = false;
    int32_t sessionId = uiContent->CreateModalUIExtension(request, extensionCallbacks, config);
    if (sessionId == 0) {
        SETTING_LOG_INFO("get sessionId faild");
        return false;
    }
    callback->SetSessionId(sessionId);
    SETTING_LOG_INFO("end StartUiExtensionAbility");
    return true;
}

OHOS::Ace::UIContent* GetUIContent(std::shared_ptr<BaseContext> &asyncContext)
{
    OHOS::Ace::UIContent* uiContent = nullptr;
    if (asyncContext->abilityContext != nullptr) {
        SETTING_LOG_INFO("get uiContext by ability context");
        uiContent = asyncContext->abilityContext->GetUIContent();
    } else if (asyncContext->uiExtensionContext != nullptr) {
        SETTING_LOG_INFO("get uiContext by ui extension ability context");
        uiContent = asyncContext->uiExtensionContext->GetUIContent();
    } else {
        SETTING_LOG_INFO("get uiContext failed.");
    }

    return uiContent;
}

